sections.text:
\keywords{Largest common subtrees, Bienaymé--Galton--Watson trees, Brownian CRT}
\subjclass[2010]{60C05, 60J80, 05C05, 05C60} 



\begin{abstract}
  We study the size and structure of the largest common subtree (LCS) between two independent Bienaym\'{e} trees conditioned to have size $n$.
  When the trees are critical with finite $2$nd and $(2+\kappa)$th moment respectively for some $\kappa>0$, we prove that the LCS has size of order $\sqrt{n}$, and is approximated by the length of three paths meeting at a central node. Moreover, we show that the largest common subtree between two critical independent Bienaymé trees with size $n$ and finite second moments may be much larger than $\sqrt{n}$, implying that our result is tight. We also pose a number of open questions and suggestions for future research.
\end{abstract}

\maketitle

For trees $t$, $t'$ and $t''$, say that $t''$ is a \emph{common subtree} of $t$ and $t'$ if $t''$ is isomorphic to a subtree of both $t$ and $t'$.
The size of the \emph{largest common subtrees} (LCS) of $t$ and $t'$ is denoted by $\LCS(t,t')$.
The purpose of this paper is the study of the LCS when $t$ and $t'$ are two independent random trees.
A natural setting is that of Bienaym\'e trees\footnote{Also known as Galton--Watson trees or family trees of branching processes.} conditioned to have size $n$.
The following theorem is a less detailed version of our main result (\cref{thm:main}).

\begin{thm}
  Let $\tau_n$ and $\tau'_n$ be independent critical Bienaymé trees conditioned to have size $n$, whose offspring distributions have a finite $(2+\kappa)$th, for some $\kappa>0$, and a finite $2$nd moment, respectively.
  Then, there is a finite random variable $X>0$ for which
  \[ n^{-1/2} \LCS(\tau_n,\tau'_n) \xrightarrow[n\to\infty]{\mathrm d} X. \] 
\end{thm}

We remark that we view trees as just graphs with no additional structure such as vertex labels or a plane embedding (even though in our proofs we use the Ulam formalism for trees wherein vertices have a natural order).

In \cref{thm:a_star_is_born}, we show that this result is tight, in the sense that having finite second moments for both offspring distributions is not sufficient. 

Our main result is \cref{thm:main} which relates the limit $X$ to the scaling limits of the Bienaym\'e trees.
To state that result, we need some additional definitions.
\smallskip

Let $\mu=(\mu(k))_{k\geq 0}$ and $\mu'=(\mu'(k))_{k\geq 0}$ be two \emph{critical and non-trivial offspring distributions}, meaning that
\begin{equation}
\label{criticality_assumption}
1=\sum_{k\geq 0}k\mu(k)=\sum_{k\geq 0}k\mu'(k)\quad\text{ and }\quad \mu(0),\mu'(0)>0.
\end{equation}
Moreover, we assume that $\mu$ and $\mu'$ have finite second moments:
\begin{equation}
\label{finite_2-moment_assumption}
\sigma^2:=\sum_{k\geq 0}(k-1)^2\mu(k)<\infty\quad\text{ and }\quad (\sigma')^2:=\sum_{k\geq 0}(k-1)^2\mu'(k)<\infty.
\end{equation}

Let us denote by $\tau$ and $\tau'$ two independent Bienaymé trees with respective offspring distributions $\mu$ and $\mu'$ (a formal definition of Bienaym\'{e} trees is given in \cref{sec:preliminaries}). 
We will hereafter only consider $n$ for which $\P(\# \tau=n)>0$ and $\P(\# \tau'=n)>0$. Then for any such $n$, denote by $\tau_n$ and $\tau_n'$ two independent Bienaymé trees with offspring distributions $\mu$ and $\mu'$, respectively, and conditioned to have size $n$. We view $\tau_n$ and $\tau_n'$ as compact metric spaces equipped with their graph distances.

For any metric space $\rE=(E,d)$ and $\lambda>0$, we write $\lambda\cdot \rE=(E,\lambda d)$ for the metric space obtained by rescaling the distances on $E$ by $\lambda$. It is now well-known \cite{aldous1993continuumIII,haas2012scaling} that 
\begin{equation}
\label{Bienayme->CRT}
\bigg(\frac{1}{\sqrt{n}}\cdot\tau_n,\frac{1}{\sqrt{n}}\cdot\tau_n'\bigg)\xrightarrow[n\to\infty]{\mathrm d}\left(\frac{2}{\sigma}\cdot \sT,\frac{2}{\sigma'}\cdot \sT'\right)
\end{equation}
with respect to the Gromov--Hausdorff topology, where $\sT$ and $\sT'$ are two independent \emph{Brownian continuum random trees (CRTs)}. More precisely, if $\be=(\be_s)_{s\in[0,1]}$ is a standard Brownian excursion, then $\sT$ and $\sT'$ have the same law as the quotient metric space of $[0,1]$ induced by the pseudo-distance $d_{\be}$ defined as follows:
\[\forall 0\leq s_1\leq s_2\leq 1,\quad d_{\be}(s_1,s_2)=\be_{s_1}+\be_{s_2}-2\min_{[s_1,s_2]}\be.\]


Finally, we introduce our limit quantity. For any two compact metric spaces $\rE=(E,d)$ and $\rE'=(E',d')$, set
\begin{multline}
\label{Phi}
\Phi(\rE,\rE')=\sup\big\{\tfrac{1}{2}d(x_1,x_2)+\tfrac{1}{2}d(x_2,x_3)+\tfrac{1}{2}d(x_3,x_1) \, :\, x_1,x_2,x_3\in E\text{ and }x_1',x_2',x_3'\in E'\\
\text{ such that }d(x_i,x_j)=d'(x_i',x_j')\text{ for all }1\leq i,j\leq 3\big\}.
\end{multline}
When $\rE$ and $\rE'$ are compact real trees (\cref{real-tree_def}), then $\Phi(\rE,\rE')$ corresponds to \emph{the maximum total length of a common Y-shaped subtree} of $\rE$ and $\rE'$: see \cref{fig:largest_y}. For details on compact real trees, the Brownian continuum random tree, and the Gromov--Hausdorff topology, we direct the reader to \cite{legall2005random} (see also \cref{sec:compact_real_tree} for a brief summary).

Now, let $\tau_*$ and $\tau'_*$ be two independent rooted trees whose laws are characterized by the following:
\begin{enumerate}
    \item[(a)] For all integers $k\geq 0$, the root of $\tau_*$ has $k$ children with probability $(k+1)\mu(k+1)$, and the root of $\tau_*'$ has $k$ children with probability $(k+1)\mu'(k+1)$.
    \item[(b)] Conditionally given the offspring size of the root in $\tau_*$ (resp.~in $\tau_*'$), the subtrees of $\tau_*$ (resp.~of $\tau_*'$) above these children are independent Bienaymé trees with offspring distribution $\mu$ (resp.~$\mu'$).
\end{enumerate}
We refer to these random rooted trees, $\tau_*$ and $\tau_*'$, as \emph{root-biased Bienaym\'{e} trees} with offspring distributions $\mu$ and $\mu'$ respectively. 

For rooted trees $t$, $t'$ and $t''$, we say that $t''$ is a \emph{common rooted subtree} of $t$ and $t'$ if there are graph isomorphisms from $t''$ to both $t$ and $t'$ that map the root to the root. Write $\LCS^\bullet(t,t')$ for the maximum size of a common rooted subtree of $t$ and $t'$.
\smallskip

We are now ready to state our main result in its full form.

\begin{thm}
\label{thm:main}
Assume that \eqref{criticality_assumption} and \eqref{finite_2-moment_assumption} hold, keep the above notation, and set $c_{\mu,\mu'}=\E\big[\LCS^\bullet(\tau_*,\tau_*')\big]$. If there exists $\kappa>0$ such that $\sum_{k\geq 0}k^{2+\kappa}\mu(k)<\infty$, then the following convergence in distribution on $\R$ holds jointly with \eqref{Bienayme->CRT}:
\[\frac{1}{\sqrt{n}}\LCS(\tau_n,\tau_n') \xrightarrow[n\to\infty]{\mathrm d} c_{\mu,\mu'}\Phi\big(\tfrac{2}{\sigma}\cdot\sT,\tfrac{2}{\sigma'}\cdot\sT'\big).\]
\end{thm}
\begin{rmk}
Our proofs in fact give, under the assumptions of \cref{thm:main}, that for any $c>0$, 
\[\frac{1}{\sqrt{n}}\LCS(\tau_n,\tau_{\lfloor cn\rfloor}') \xrightarrow[n\to\infty]{\mathrm d} c_{\mu,\mu'}\Phi\big(\tfrac{2}{\sigma}\cdot\sT,\tfrac{2\sqrt{c}}{\sigma'}\cdot\sT'\big),\]
but to ease notation we will not prove this more general theorem.
\end{rmk}

Let us briefly present some concrete examples of cases where \cref{thm:main} applies. The family of size-conditioned critical Bienaym\'{e} trees with finite variance offspring distributions contains several usual combinatorial families of random trees. In fact, one does not need to even look past offspring distributions with finite exponential moments to find many well-studied models. Here are a few examples:
\begin{itemize}
    \item If we set $\mu(d) =1-\mu(0) =  1/d$ for some $d\geq 2$, then $\tau_n$ is distributed as a uniform $d$-ary tree on $n$ vertices (assuming that $n = md + 1$ for some integer $m \geq 0$).
    \item If we set $\mu(k) = 2^{-(k+1)}$ for all $k \geq 0$, then $\tau_n$ is distributed as a uniform rooted plane tree on $n$ vertices.
    \item If we set $\mu(k) = {e^{-1}}/{k!}$ for all $k \geq 0$, then after randomly labelling the vertices, $\tau_n$ is distributed as a uniform labelled tree on $n$ vertices.
\end{itemize}
\cref{thm:main} applies to any pair of trees from the above list (again, ignoring the labels and plane order when looking for common subtrees).


One may wonder if the condition that one of the two offspring distributions has to have a finite $(2+\kappa)$th moment is necessary, or just a consequence of techniques. The following result shows that \cref{thm:main} is false if we allow $\kappa=0$, implying that our theorem is tight in this generality. 

\begin{thm}\label{thm:a_star_is_born}
    For any $\gamma < 1/2$, there exists a critical and non-trivial offspring distribution $\mu$ satisfying $\sum_{k\ge 0}k^2\mu(k)<\infty$ such that for $\mu'=\mu$, with high probability $\LCS(\tau_n,\tau'_n) \geq \sqrt{n} \log^\gamma n$ as $n\to\infty$.
\end{thm}

We prove this theorem in \cref{sec:a_star_is_born}.

We begin by introducing the plane tree formalism. Note that the specific ordering of offspring is irrelevant for the notion of common (rooted) subtrees; we use the notation only for convenience of labelling vertices in our trees.

Denote by $\N^*=\{1,2,3,\ldots\}$ the set of positive integers and by $\U$ the set of finite words written with the alphabet $\N^*$, that is,
\[\U=\bigcup_{\ell\geq 0}(\N^*)^\ell\quad\text{ with the convention }\quad(\N^*)^0=\{\varnothing\}.\]
As a set of words, $\U$ is totally ordered by the \emph{lexicographic order} $\leq$, so that $\varnothing<(1)<(1,2)<(2)$ for example. For two words $u=(u_1,\ldots,u_\ell)$ and $v=(v_1,\ldots,v_m)$, we write $u*v=(u_1,\ldots,u_\ell,v_1,\ldots,v_m)$ for their concatenation. We also denote by $|u|=\ell$ the length of $u$, with $|\varnothing|=0$, which we call \emph{the height of $u$}. Moreover, if $u\neq\varnothing$ then we call $\overleftarrow{u}:=(u_1,\ldots,u_{\ell-1})$ \emph{the parent of $u$}. If $u,v\in \U\setminus\{\varnothing\}$ have the same parent and if $u\leq v$, we say that $u$ is an \emph{older sibling} of $v$ and that $v$ is a \emph{younger sibling} of $u$.  We also define the \emph{genealogical order} $\preceq$ on $\U$, which is the partial ordering generated by the covering relation\footnote{For a partially ordered set $(\mathcal{P},\prec)$, $y\in \mathcal{P}$ covers $x\in \mathcal{P}$ if $x\prec y$ and for all $z\in \mathcal{P}$, if $x\preceq z \preceq y$ then $z=x$ or $z=y$.} $u\in t$ covers $v\in t$ if and only if $v=\overleftarrow{u}$. Then $u\preceq v$ if and only if there is a $w\in \mathbb{U}$ so that $v=u*w$. If $u\preceq v$ we say that $u$ is an \emph{ancestor of $v$}. We also write $u \prec v$ to express that $u \preceq v$ and $u \ne v$. 

\begin{defn}
\label{def:tree}
A \emph{plane tree} is a (potentially infinite) subset $t$ of $\U$ satisfying the following conditions:
\begin{enumerate}
    \item[(a)] $\varnothing\in t$,
    \item[(b)] for all $u\in t$, if $u\neq\varnothing$ then $\overleftarrow{u}\in t$,
    \item[(c)] for all $u\in t$, there is an integer $\rk_u(t)\geq 0$ such that $u * (i)\in t \Leftrightarrow 1\leq i\leq  \rk_u(t)$ for all $i \in \N^*$.
\end{enumerate}
\end{defn}

Let $t$ be a plane tree. We call $\varnothing$ the \emph{root} of $t$. For $u\in t$, we call $\{u\! *\! (i) : 1\leq i \leq \rk_u(t)\}$ the \emph{children of $u$ in $t$}. A \emph{leaf of $t$} is a vertex $u\in t$ such that $\rk_u(t)=0$. We shall always view a plane tree $t$ as a rooted graph whose set of vertices is $t$, whose edges are the $\{\overleftarrow{u},u\}$ for $u\in t\setminus\{\varnothing\}$, and whose root is $\varnothing$. In particular, when $t$ and $t'$ are two plane trees, the quantities $\LCS(t,t')$ and $\LCS^\bullet(t,t')$ are well-defined. Also note that an injection $\phi:t'\to t$ is an isomorphic embedding of rooted graphs if and only if $\phi(\emptyset)=\emptyset$ and $\overleftarrow{\phi(u)}=\phi(\overleftarrow{u})$ for all $u\in t'\setminus\{\varnothing\}$. Finally, see that $\rk_u(t)$ is the out-degree of $u$ in the rooted graph $(t,\varnothing)$.
\smallskip

For $u\in t$, we respectively define the \emph{subtree rooted at $u$} and the subtree pruned above $u$:
\[\theta_u t=\{v\in \U :u*v\in t\}\quad\text{ and }\quad \Cut_u t=t\setminus\{u*v\in t: v\in (\theta_u t)\setminus\{\varnothing\}\}.\]
Also see \cref{fig:basic-defs}. 
Note that $\theta_u t$ and $\Cut_u t$ are plane trees in the sense of \cref{def:tree}. Now assume that $u\neq\varnothing$ and write $u=v*(i)$ with $1\leq i\leq \rk_v(t)$. We define
\[\Trim_u t=\{\varnothing\}\cup\{(j)*w\, :\, 1\leq j<i,w\in\theta_{v*(j)}t\}\cup\{(j-1)*w\, :\, i< j\leq \rk_v(t),w\in\theta_{v*(j)}t\}.\]
Also see \cref{fig:basic-defs}. 
Informally, $\Trim_u t$ is obtained by removing the subtree of $t$ rooted at $u$ from the subtree rooted at its parent $\overleftarrow{u}$.

With our plane tree notation, we can formally define Bienaym\'{e} trees and two variants of Bienaym\'{e} trees which are relevant to us. For the following definition, and the rest of the paper, we use the notation $\N = \{0,1,2,...\}$.

\begin{defn}
Let $\mu$ be a measure on $\N$. A random plane tree $\tau$ is called a \emph{Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] The law of $\rk_\emptyset(\tau)$ is $\mu$.
    \item[(b)] For all $k \geq 1$ such that $\mu(k) > 0$, conditionally given that $\rk_\emptyset(\tau) = k$, the subtrees $\theta_1\tau,...,\theta_k\tau$ are i.i.d.~and with the same law as $\tau$.
\end{enumerate}
We frequently call (b) \emph{the branching property} of Bienaymé trees. If $\sum_{k \geq 0} k\mu(k) = 1$ and $\mu(0) > 0$, then we call $\tau$ and $\mu$ \emph{critical}, and it is well-known that $\tau$ is almost surely finite.
\end{defn}

\begin{defn}
\label{def:root-biased}
Let $\mu$ be a critical measure on $\N$. A random plane tree $\tau_*$ is called a \emph{root-biased Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] For all $k \geq 0$, $\prob(\rk_\emptyset(\tau_*) = k) = (k+1)\mu(k+1)$.
    \item[(b)] For all $k \geq 1$ such that $\prob(\rk_\emptyset(\tau_*) = k) > 0$, conditionally given that $\rk_{\emptyset}(\tau_*) = k$, $\theta_1\tau,...,\theta_k\tau$ are independent Bienaym\'{e} trees with offspring distribution $\mu$.
\end{enumerate}
\end{defn}

Let $\mu$ be a probability measure on $\N$ such that $\mu(0)>0$ and $m_\mu:=\sum_{k\geq 0}k\mu(k)\in(0,\infty)$.

\begin{defn}\label{def:size-biased-tree}
Let $\tau_\infty$ be a random infinite plane tree and $U_\infty=(J_i)_{i\geq 1}$ be a sequence of random positive integers. Set $U_0=\varnothing$ and $U_n=(J_1,\ldots,J_n)$ for all $n\geq 1$. We say that $(\tau_\infty,U_\infty)$ is a \emph{size-biased Bienaymé tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] For all $n\geq 0$, $U_n$ is almost surely an element of $\tau_\infty$.

    \item[(b)] The random pairs $(\rk_{U_n}(\tau_\infty),J_{n+1})$ for $n\geq 0$ are i.i.d.~and distributed as follows:
    \[\forall k,j\in\N^*,\quad \P(\rk_{U_n}(\tau_\infty)=k\, ;\, J_{n+1}=j)=\I{j\leq k}\mu(k)/m_\mu.\]

    \item[(c)] Conditionally given $(\rk_{U_n}(\tau_\infty),J_{n+1})_{n\geq 0}$, the random plane trees $\theta_{U_n*(j)}\tau_\infty$ for $n\geq 0$ and $j\in \{1,\ldots,\rk_{U_n}(\tau_\infty)\}\setminus\{J_{n+1}\}$ are independent Bienaymé trees with offspring distribution $\mu$.
\end{enumerate}
\end{defn}

Comparing \cref{def:root-biased,def:size-biased-tree} readily gives the following result.

\begin{prop}
\label{root-biased_VS_size-biased}
Let $(\tau_\infty,U_\infty)$ be a size-biased Bienaymé tree with offspring distribution $\mu$ as above. Then, the random plane trees $\Trim_{U_n}\tau_\infty$ for $n\geq 1$ are independent root-biased Bienaymé trees with offspring distribution $\mu$.
\end{prop}

